/**
 * Cortada Capital Group marks, inlined as data URIs.
 *
 * They have to be data URIs rather than /public URLs: the generated block is
 * COPIED INTO an email, and a mail client rendering an <img> that points at
 * the CRM would either 404 for the merchant or leak that they opened it.
 * Embedding the bytes means the pasted email carries its own logo.
 *
 * Two images, exactly as the original tool had them — the tool header uses a
 * square mark, the email masthead a wider lockup. They are NOT interchangeable.
 */

/** Square mark shown in the builder's own header. */
export const CORTADA_MARK_DATA_URI =
  'data:image/png;base64,';

/** Wide lockup used at the top of the generated merchant email. */
export const CORTADA_EMAIL_LOGO_DATA_URI =
  'data:image/png;base64,';
